const Icon=({icon:Comp=BookOpen,...props})=><Comp size={20} strokeWidth={1.8} {...props}/>;
function Brand({settings,inverse=false}) {return <span className={`brand ${inverse?'inverse':''}`}>{settings.logo&&safeUrl(settings.logo)?<img src={safeUrl(settings.logo)} alt={settings.brand}/>:<span className="brand-mark"><i/><i/><i/><span/></span>}<span>{settings.brand==='Sure60'?<>Sure<span className="brand60">60<span className="brand-dot">.</span></span></>:settings.brand}<small>{settings.tagline}</small></span></span>}
function Modal({title,children,onClose,wide=false}) {const ref=useRef(),closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const previous=document.activeElement;ref.current?.focus();const handler=e=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const all=ref.current?.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]');if(!all?.length)return;const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',handler);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',handler);document.body.style.overflow=old;previous?.focus()}},[]);return <div className="modal-shade" onClick={e=>{if(e.target===e.currentTarget)onClose()}}><section ref={ref} tabIndex={-1} className={`modal ${wide?'wide':''}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" aria-label="Close dialog" onClick={onClose}><X/></button></div>{children}</section></div>}
function Empty({icon=BookOpen,title,children}){return <div className="empty"><Icon icon={icon} size={34}/><h3>{title}</h3><p>{children}</p></div>}
function Field({label,children,...props}){return <label className="field"><span>{label}</span>{children||<input {...props}/>}</label>}
function App(){
 const [settings,setSettings]=useState(defaults),[batches,setBatches]=useState(configured?[]:sampleBatches),[tests,setTests]=useState(configured?[]:sampleTests),[profile,setProfile]=useState(null),[page,setPage]=useState(()=>window.location.pathname.replace(/\/$/,'')===`${import.meta.env.BASE_URL}Avinash`?'admin':'home'),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[menu,setMenu]=useState(false),[activeTest,setActiveTest]=useState(null),[boot,setBoot]=useState(configured);
 const notify=message=>setToast(message);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),5500);return()=>clearTimeout(t)}},[toast]);
 async function loadPublic(){if(!db)return;try{const [s,b,t]=await Promise.all([query('site_settings'),query('batches',{order:'created_at'}),query('tests',{eq:{published:true},order:'created_at'})]);if(s[0])setSettings({...defaults,...s[0].data});setBatches(b);setTests(t)}catch(e){notify('Database setup needed: '+e.message)}}
 async function loadProfile(session){if(!session){setProfile(null);return}try{const rows=await query('profiles',{eq:{id:session.user.id}});if(!rows[0]?.verified){setProfile(null);setActiveTest(null);await db.auth.signOut();return}setProfile(rows[0])}catch(e){setProfile(null);setActiveTest(null);await db.auth.signOut();notify(e.message)}}
 useEffect(()=>{loadPublic();if(!db)return;let live=true;db.auth.getSession().then(async({data})=>{if(live)await loadProfile(data.session);if(live)setBoot(false)});const {data:{subscription}}=db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){setProfile(null);setActiveTest(null);}else setTimeout(()=>{if(live)loadProfile(session)},0)});return()=>{live=false;subscription.unsubscribe()}},[]);
 useEffect(()=>{const onPop=()=>{setPage(window.location.pathname.replace(/\/$/,'')===`${import.meta.env.BASE_URL}Avinash`?'admin':'home');setModal(null)};window.addEventListener('popstate',onPop);return()=>window.removeEventListener('popstate',onPop)},[]);
 function navigate(where){const path=where==='admin'?`${import.meta.env.BASE_URL}Avinash`:import.meta.env.BASE_URL;if(window.location.pathname!==path)window.history.pushState({},'',path);setPage(where);setMenu(false);window.scrollTo({top:0,behavior:'smooth'})}
 function section(id){if(page!=='home'){navigate('home');setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),100)}else document.getElementById(id)?.scrollIntoView({behavior:'smooth'});setMenu(false)}
 function studentAction(target='dashboard'){if(profile?.verified||profile?.role==='admin')navigate(target);else if(profile)setModal({type:'pending'});else setModal({type:'login'})}
 async function signOut(){await db?.auth.signOut();setProfile(null);setActiveTest(null);navigate('home')}
 return <>{settings.announcement&&settings.announcement!==defaults.announcement&&<div className="announcement"><span><Sparkles size={13}/>{settings.announcement}</span></div>}<header className="header"><div className="container nav"><button className="brand-button" aria-label="Sure60 home" onClick={()=>navigate('home')}><Brand settings={settings}/></button><nav id="main-navigation" className={menu?'open':''}><button className={page==='home'?'active':''} onClick={()=>navigate('home')}>Home</button><button onClick={()=>section('batches')}>Our Batches <ChevronDown size={13}/></button><button onClick={()=>navigate('tests')} className={page==='tests'?'active':''}>Test Series</button><button onClick={()=>section('why')}>Why Sure60?</button><button onClick={()=>section('contact')}>Contact Us</button></nav><div className="nav-actions">{profile?<><button className="btn small" onClick={()=>studentAction()}>My Batches <ArrowUpRight size={15}/></button><button className="icon-btn logout" title="Sign out" onClick={signOut}><LogOut size={18}/></button></>:<button className="btn small" onClick={()=>setModal({type:'login'})}>Student Login <ArrowUpRight size={16}/></button>}<button className="icon-btn menu-toggle" aria-label="Toggle menu" aria-expanded={menu} aria-controls="main-navigation" onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></div></header>
 {boot?<div className="loading-page"><Loader2 className="spin"/> Loading your learning space…</div>:activeTest?<TestPlayer test={activeTest} profile={profile} notify={notify} onExit={()=>{setActiveTest(null);navigate('tests')}} onComplete={result=>{setActiveTest(null);setModal({type:'result',result,test:activeTest});navigate('tests')}}/>:page==='home'?<Home settings={settings} batches={batches} tests={tests} section={section} navigate={navigate} openBatch={batch=>setModal({type:'batch',batch})} studentAction={studentAction} openLogin={()=>setModal({type:'login'})} setModal={setModal}/>:page==='tests'?<TestList tests={tests} profile={profile} setModal={setModal} onStart={test=>{if(test.id==='demo-test'||profile?.verified||profile?.role==='admin')setActiveTest(test);else studentAction()}}/>:page==='admin'?(profile?.role==='admin'&&profile?.verified?<Admin settings={settings} setSettings={setSettings} batches={batches} reload={loadPublic} notify={notify} profile={profile}/>:<main className="container dashboard"><section className="admin-login-card"><span className="eyebrow">KARNAL CAMPUS · SECURE WORKSPACE</span><h1>Administrator login</h1><p className="muted">Administrator sign in</p><Login admin notify={notify} onSuccess={async user=>{await loadProfile({user});navigate('admin')}}/><p className="micro muted">This address is not a password. Access is checked by Supabase account permissions.</p></section></main>):<StudentDashboard profile={profile} batches={batches} notify={notify} onTests={()=>navigate('tests')}/>}
 <Footer settings={settings} section={section} navigate={navigate}/>
 {modal&&<Modal title={{login:'Welcome back.',pending:'Your learning journey is almost ready',batch:modal.batch?.title,result:'Your effort. Your progress.',leaderboard:'The leaderboard',contact:'Let’s talk about your future'}[modal.type]||'Sure60'} wide={['leaderboard','batch'].includes(modal.type)} onClose={()=>setModal(null)}>
 {modal.type==='login'&&<Login notify={notify} onSuccess={async user=>{await loadProfile({user});setModal(null);navigate('dashboard')}}/>}
 {modal.type==='pending'&&<><div className="notice"><ShieldCheck/><p>Your account is registered and awaiting admin verification. After verification, your assigned batches and tests will unlock.</p></div><button className="btn full" onClick={async()=>{const {data}=await db.auth.getSession();await loadProfile(data.session);setModal(null);navigate('dashboard')}}>Check approval status <ArrowRight size={17}/></button></>}
 {modal.type==='batch'&&<BatchDetails batch={modal.batch} onEnroll={()=>{setModal(null);studentAction()}} configured={configured}/>}
 {modal.type==='result'&&<Result result={modal.result} test={modal.test} onRank={()=>setModal({type:'leaderboard',test:modal.test})}/>}
 {modal.type==='leaderboard'&&<Leaderboard test={modal.test} notify={notify}/>}
 {modal.type==='contact'&&<><p>Visit our Karnal campus to meet the team and find your batch.</p><div className="notice"><MapPin/><p>{settings.address}</p></div>{settings.phone?<a className="btn full" href={`tel:${settings.phone.replace(/[^\d+]/g,'')}`}>Call the campus</a>:<p className="muted">Campus phone and social links will be published by the administrator.</p>}</>}
 </Modal>}{toast&&<div className="toast" role="status"><CheckCircle2 size={20}/><span>{toast}</span><button onClick={()=>setToast('')} aria-label="Dismiss"><X size={16}/></button></div>}
 </>
}
// CSS geometry creates real spatial depth without a WebGL bundle or render loop.
function LearningScene({settings,slide,paused,palette,onPalette}) {
 const [view,setView]=useState('3d'),[visible,setVisible]=useState(true),[pageVisible,setPageVisible]=useState(!document.hidden);
 const ref=useRef(null),frame=useRef(0),angles=useRef({x:0,y:0}),drag=useRef(null);
 const active=visible&&pageVisible&&!paused;
 const reducedMotion=useRef(window.matchMedia('(prefers-reduced-motion: reduce)'));
 function rotate(x,y){
  if(reducedMotion.current.matches){x=0;y=0}
  angles.current={x:Math.max(-12,Math.min(12,x)),y:Math.max(-28,Math.min(28,y))};
  cancelAnimationFrame(frame.current);
  frame.current=requestAnimationFrame(()=>{
   ref.current?.style.setProperty('--pitch',`${angles.current.x}deg`);
   ref.current?.style.setProperty('--yaw',`${angles.current.y}deg`);
  });
 }
 useEffect(()=>{
  const observer='IntersectionObserver' in window?new IntersectionObserver(([entry])=>setVisible(entry.isIntersecting),{threshold:0.05}):null;
  if(ref.current)observer?.observe(ref.current);
  const visibility=()=>setPageVisible(!document.hidden);
  document.addEventListener('visibilitychange',visibility);
  return()=>{observer?.disconnect();document.removeEventListener('visibilitychange',visibility);cancelAnimationFrame(frame.current)};
 },[]);
 useEffect(()=>{if(paused){drag.current=null;rotate(0,0)}},[paused]);
 const image=safeUrl(slide===0?settings.hero:settings[`hero${slide+1}`]||settings.hero)||`${import.meta.env.BASE_URL}students.jpg`;
 return <figure ref={ref} className="learning-scene" data-active={active} data-chapter={slide} aria-label="Interactive three-dimensional learning illustration">
  <div className="scene-switch" role="group" aria-label="Hero visual style">
   <button aria-pressed={view==='3d'} onClick={()=>setView('3d')}><Sparkles size={13}/>3D view</button>
   <button aria-pressed={view==='campus'} onClick={()=>setView('campus')}><Users size={13}/>Campus view</button>
  </div>
  {view==='3d'?<>
   <div className="scene-stage" onPointerDown={e=>{if(!active)return;drag.current={x:e.clientX,y:angles.current.y};if(e.pointerType!=='mouse'&&e.currentTarget.hasPointerCapture?.(e.pointerId)===false){try{e.currentTarget.setPointerCapture(e.pointerId)}catch{/* Synthetic pointers do not have native capture. */}}}}
    onPointerMove={e=>{if(!active)return;const bounds=e.currentTarget.getBoundingClientRect();if(e.pointerType==='mouse')rotate(-(e.clientY-bounds.top-bounds.height/2)/24,(e.clientX-bounds.left-bounds.width/2)/12);else if(drag.current)rotate(0,drag.current.y+(e.clientX-drag.current.x)/4)}}
    onPointerUp={()=>{drag.current=null}} onPointerCancel={()=>{drag.current=null}} onPointerLeave={e=>{if(e.pointerType==='mouse'){drag.current=null;rotate(0,0)}}}>
    <div className="scene-grid" aria-hidden="true"/>
    <div className="scene-parallax" aria-hidden="true">
     <div className="orbital-sculpture">
      <div className="sculpture-orbit orbit-a"/><div className="sculpture-orbit orbit-b"/>
      <div className="sculpture-float">
       {['first','second'].map(side=><div className={`sculpture-ring ring-${side}`} key={side}>{Array.from({length:18},(_,i)=><i key={i} style={{'--layer':i}}/>)}</div>)}
       <div className="sculpture-core"><span>60<span>.</span></span></div>
      </div>
     </div>
     <span className="scene-sphere sphere-lime"/><span className="scene-sphere sphere-blue"/><span className="scene-sphere sphere-purple"/>
     <div className="floating-symbol symbol-plus">+</div><div className="floating-symbol symbol-asterisk">✳</div>
     <div className="learning-chip"><span className="chip-icon"><GraduationCap size={22}/></span><strong>{['A brighter beginning.','A little more confidence.','Your next big step.'][slide]}</strong><ArrowUpRight size={16}/></div>
    </div>
    <div className="scene-shadow" aria-hidden="true"/>
   </div>
   <div className="palette-picker" role="group" aria-label="Colour palette">{['spectrum','sunset','ocean'].map(tone=><button key={tone} className={`palette-swatch swatch-${tone}`} aria-label={`${tone[0].toUpperCase()+tone.slice(1)} colours`} aria-pressed={palette===tone} title={`${tone[0].toUpperCase()+tone.slice(1)} colours`} onClick={()=>onPalette(tone)}><span/>{palette===tone&&<Check size={12}/>}</button>)}</div>
   <figcaption className="scene-caption"><span><span className="live-dot"/>{paused?'Motion paused':'Move or drag to explore'}</span><div className="scene-controls" role="group" aria-label="Rotate illustration"><button disabled={paused} onClick={()=>rotate(0,angles.current.y-12)} aria-label="Rotate 3D scene left"><ChevronLeft size={16}/></button><button disabled={paused} onClick={()=>rotate(0,0)} aria-label="Reset 3D scene">Reset</button><button disabled={paused} onClick={()=>rotate(0,angles.current.y+12)} aria-label="Rotate 3D scene right"><ChevronRight size={16}/></button></div></figcaption>
  </>:<div className="campus-scene"><img src={image} alt="Students sharing ideas and preparing together" onError={e=>{const fallback=new URL(`${import.meta.env.BASE_URL}students.jpg`,location.origin).href;if(e.currentTarget.src!==fallback)e.currentTarget.src=fallback}}/><div><span className="live-dot"/> A place to grow. Together.</div></div>}
 </figure>;
}
function AnimatedHeading({text}) {
 let wordIndex=0,letterIndex=0;
 return <h1 aria-label={text.replaceAll('\n',' ')}>{text.split('\n').map((line,i)=><span className={`headline-line ${i===1?'highlight':''}`} key={i} aria-hidden="true">{line.split(' ').map((word,j)=><React.Fragment key={j}><span className="word-mask"><span style={{'--word':wordIndex++}}>{Array.from(word).map((letter,k)=><span className="animated-letter" key={k} style={{'--letter':letterIndex++}}>{letter}</span>)}</span></span>{' '}</React.Fragment>)}</span>)}</h1>;
}
function Home({settings,batches,section,navigate,openBatch,setModal}){
 const [palette,setPalette]=useState('spectrum');
 const [slide,setSlide]=useState(0),[filter,setFilter]=useState('All Exams'),[paused,setPaused]=useState(()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches),[hovered,setHovered]=useState(false);
 const slides=[
  {title:settings.heroTitle===defaults.heroTitle?'Your future.\nIn full colour.':settings.heroTitle,sub:settings.heroSubtitle===defaults.heroSubtitle?'Find your focus. Make your next move.':settings.heroSubtitle},
  {title:settings.heroTitle2||'Small steps.\nLimitless you.',sub:settings.heroSubtitle2||'Build confidence, one lesson at a time.'},
  {title:settings.heroTitle3||'Dream bigger.\nGo further.',sub:settings.heroSubtitle3||'A little practice. A world of possibility.'}
 ];
 useEffect(()=>{const media=window.matchMedia('(prefers-reduced-motion: reduce)');const update=()=>setPaused(media.matches);media.addEventListener('change',update);return()=>media.removeEventListener('change',update)},[]);
 useEffect(()=>{if(paused||hovered)return;const t=setInterval(()=>{if(!document.hidden)setSlide(s=>(s+1)%3)},8000);return()=>clearInterval(t)},[paused,hovered]);
 useEffect(()=>{
  const elements=document.querySelectorAll('.section-heading,.batch-card,.why-cards article,.practice-banner,.faq-section,.trust-strip>div');
  if(paused||!('IntersectionObserver' in window))return;
  const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target)}}),{threshold:0.08});
  elements.forEach(el=>{el.classList.add('reveal');observer.observe(el)});
  return()=>{observer.disconnect();elements.forEach(el=>el.classList.remove('reveal'))};
 },[filter,paused,batches]);
 const filters=['All Exams','SSC','Haryana CET','Banking','Railways','Defence'];
 const shown=batches.filter(b=>filter==='All Exams'||b.category===filter);
 return <main data-palette={palette} className={`home-experience ${paused?'motion-paused':''}`}>
  <section className="hero" aria-label="Discover Sure60" aria-roledescription="carousel" onMouseEnter={()=>setHovered(true)} onMouseLeave={()=>setHovered(false)} onFocusCapture={()=>setHovered(true)} onBlurCapture={e=>{if(!e.currentTarget.contains(e.relatedTarget))setHovered(false)}}>
   <div className="container hero-grid">
    <div className="hero-copy" key={slide}>
     <div className="eyebrow"><span/> LEARNING, WITH A NEW PERSPECTIVE</div>
     <AnimatedHeading text={slides[slide].title}/>
     <p className="hero-sub">{slides[slide].sub}</p>
     <div className="hero-buttons"><button className="btn" onClick={()=>section('batches')}>Explore Our Batches <ArrowUpRight size={18}/></button><button className="btn outline" onClick={()=>navigate('tests')}><span className="play-circle"><Play size={11} fill="currentColor"/></span> Try a Free Test</button></div>

    </div>
    <LearningScene settings={settings} slide={slide} paused={paused} palette={palette} onPalette={setPalette}/>
   </div>
   <div className="container hero-bottom"><div className="slide-dots" aria-label="Hero slides">{slides.map((_,i)=><button key={i} onClick={()=>setSlide(i)} className={slide===i?'selected':''} aria-label={`Show slide ${i+1}`} aria-pressed={slide===i}/>)}</div><span><MapPin size={13}/> LEARN. PRACTICE. BECOME.</span><div className="slide-arrows"><button onClick={()=>setPaused(!paused)} aria-label={paused?'Play animations':'Pause animations'} aria-pressed={paused}>{paused?<Play size={14}/>:<Pause size={14}/>}</button><button onClick={()=>setSlide((slide+2)%3)} aria-label="Previous slide"><ChevronLeft size={16}/></button><button onClick={()=>setSlide((slide+1)%3)} aria-label="Next slide"><ChevronRight size={16}/></button></div></div>
  </section>
  <section className="trust-strip container" aria-label="Learning benefits">{[[GraduationCap,'Expert mentors'],[FileText,'Exam-ready practice'],[MonitorPlay,'Learn anywhere'],[ShieldCheck,'Personal guidance']].map(([Comp,label],i)=><div key={label}><span className={`trust-icon ${['mint','peach','lavender','yellow'][i]}`}><Comp size={20}/></span><strong>{label}</strong></div>)}</section>
  <section id="batches" className="section container"><div className="section-heading"><div><span className="eyebrow">01 / YOUR DIRECTION</span><h2>Your goal. <span className="soft-text">Your batch.</span></h2></div><button className="text-link" onClick={()=>{setFilter('All Exams');document.getElementById('batch-grid')?.scrollIntoView({behavior:'smooth',block:'center'})}}>View all batches <ArrowUpRight size={18}/></button></div><div className="filter-tabs" role="group" aria-label="Filter batches">{filters.map(f=><button key={f} className={filter===f?'active':''} aria-pressed={filter===f} onClick={()=>setFilter(f)}>{f}</button>)}</div><div className="batch-grid" id="batch-grid">{shown.length?shown.map(batch=><BatchCard batch={batch} key={batch.id} onClick={()=>openBatch(batch)}/>):<Empty title="New batches coming soon">Explore another exam or contact our campus.</Empty>}</div>{!configured&&<p className="demo-caption">Preview batches · Contact campus for live admissions.</p>}</section>
  <section className="why-section" id="why"><div className="container"><div className="section-heading"><div><span className="eyebrow">02 / YOUR ADVANTAGE</span><h2>Built around <span className="soft-text">you.</span></h2></div><button className="text-link" onClick={()=>setModal({type:'contact'})}>Meet your next chapter <ArrowUpRight size={18}/></button></div><div className="why-cards">{[{icon:Users,color:'lavender',title:'Real mentors.',},{icon:Target,color:'mint',title:'Clear direction.',},{icon:BarChart3,color:'yellow',title:'Visible progress.',}].map((x,i)=><article key={x.title}><div className="feature-top"><span className={`feature-icon ${x.color}`}><Icon icon={x.icon} size={25}/></span><span>0{i+1}</span></div><h3>{x.title}</h3></article>)}</div></div></section>
  <section className="section container practice-section"><div className="practice-banner"><div className="practice-art" aria-hidden="true"><div className="paper"><CheckCircle2 size={27}/><div/><div/><p>YOUR NEXT</p><strong>big step.</strong></div><span className="art-trophy"><Trophy size={30}/></span></div><div className="practice-copy"><span className="eyebrow">03 / YOUR NEXT MOVE</span><h2>Ready. Set. <span>Grow.</span></h2><p>A little practice goes a long way.</p></div><button className="btn" onClick={()=>navigate('tests')}>Take a Test <ArrowUpRight size={18}/></button></div></section>
  <section className="section container faq-section" id="faq"><div className="faq-intro"><span className="eyebrow">GOOD TO KNOW</span><h2>A little <span className="soft-text">clarity.</span></h2><button className="text-link" onClick={()=>setModal({type:'contact'})}>Talk to us <ArrowUpRight size={18}/></button></div><div className="faq-list">{[
   ['Where do I start?','Choose your exam and explore a batch. Contact our Karnal campus for current admissions.'],
   ['Can I learn on my phone?','Yes. Classes, PDF notes and practice tests work on your phone, tablet and computer.'],
   ['How do I access my classes?','Register with your roll number once live login is connected. After admin approval and batch assignment, your classes appear in My Batches.'],
   ['Can I try a free test?','Yes. Try a five-question timed demo without signing in. Demo scores stay on your device, not on a live leaderboard.']
  ].map(([question,answer])=><details key={question}><summary>{question}<Plus size={18}/></summary><p>{answer}</p></details>)}</div></section>
 </main>;
}
function BatchCard({batch,onClick}){return <article className="batch-card"><div className={`batch-cover ${batch.color||'mint'}`} style={safeUrl(batch.image_url)?{backgroundImage:`linear-gradient(90deg,rgba(255,255,255,.7),rgba(255,255,255,.1)),url("${safeUrl(batch.image_url)}")`,backgroundSize:'cover'}:{}}><span className="batch-tag"><span/>{batch.tag||'ENROLLMENT OPEN'}</span><div className="cover-copy"><small>{batch.category}</small><h3>{batch.title}</h3></div><div className="cover-art" aria-hidden="true"><Icon icon={batch.category==='Banking'?Landmark:batch.category==='Haryana CET'?Building2:GraduationCap} size={70} strokeWidth={1.3}/><span/><i/></div><span className="cover-bottom">HINDI + ENGLISH <span>FULL COURSE <ArrowUpRight size={12}/></span></span></div><div className="batch-body"><div className="batch-mode"><span><span/>{batch.mode||'Recorded'}</span><small><Clock size={13}/>{batch.duration}</small></div><div className="batch-subjects"><BookOpen size={14}/>{batch.subjects}</div><div className="batch-bottom"><div><strong>{batch.price?`₹${batch.price}`:'Contact us'}</strong><small>{batch.price?'Complete course':'Enrollment details'}</small></div><button className="btn outline small" onClick={onClick} aria-label={`View Batch: ${batch.title}`}>View Batch <ArrowUpRight size={16}/></button></div></div></article>}
