function TestCard({test,profile,onStart,onRank}){const [ranks,setRanks]=useState([]);useEffect(()=>{if(db&&profile?.verified)rpc('get_leaderboard',{p_test:test.id}).then(setRanks).catch(()=>{})},[test.id,profile]);const mine=ranks.find(r=>r.student_id===profile?.id);return <article className="test-card"><div className="test-card-top"><span className="feature-icon mint"><FileText size={24}/></span><span className="pill">{test.id==='demo-test'?'FREE DEMO':test.category||'MOCK TEST'}</span></div><h2><button className="test-title-link" onClick={onRank} title="Open complete leaderboard">{test.title}</button></h2><p>{test.description||'A focused practice session for your next big achievement.'}</p><div className="test-meta"><span><FileText size={15}/>{test.question_count} questions</span><span><Clock size={15}/>{test.duration_minutes} minutes</span></div><p className="micro">+{test.marks} correct · −{test.negative_marks} incorrect</p>{ranks.length>0&&<div className="top-ranks"><small><Trophy size={14}/> TOP PERFORMERS · {ranks.length} completed</small>{ranks.slice(0,3).map(r=><div key={r.student_id}><b>#{r.rank}</b><span>{r.full_name}</span><small>{r.correct} right · {r.wrong} wrong</small></div>)}</div>}{mine&&<div className="notice">Your rank #{mine.rank} · {mine.correct} right · {mine.wrong} wrong</div>}<div className="test-actions"><button className="btn" onClick={mine?onRank:onStart}>{mine?'View my ranking':'Start test'} <ArrowRight size={17}/></button><button className="text-link" onClick={onRank}><Trophy size={16}/> Rankings</button></div></article>}
