 async function submit(auto=false){if(submitting.current||!ready.current||(auto&&Date.now()<retryAfter.current))return;submitting.current=true;setBusy(true);setConfirm(false);try{let result;if(demo){let correct=0,wrong=0;for(const q of questions){if(answerRef.current[q.id]!==undefined){if(answerRef.current[q.id]===q.answer)correct++;else wrong++}}result={correct,wrong,unanswered:questions.length-correct-wrong,score:correct*test.marks-wrong*test.negative_marks};sessionStorage.removeItem(key)}else{await saveQueue.current;result=await rpc('submit_test',{p_attempt:attempt.current,p_answers:answerRef.current})}onComplete(result)}catch(e){setError('Submission failed. '+e.message+' Please retry; your saved answers remain available.');submitting.current=false;retryAfter.current=Date.now()+5000;setBusy(false)}}
